pragma solidity >=0.8.0;

contract IntDivOverflowWidths {
    uint256 public count;

    function okDiv16() external returns (int16) {
        int16 x = type(int16).min / int16(2);
        count += 1;
        return x;
    }

    function boomDiv16() external returns (int16) {
        int16 x = type(int16).min / int16(-1);
        count += 1;
        return x;
    }

    function boomDiv64() external returns (int64) {
        int64 x = type(int64).min / int64(-1);
        count += 1;
        return x;
    }

    function boomDiv128() external returns (int128) {
        int128 x = type(int128).min / int128(-1);
        count += 1;
        return x;
    }

    function boomDiv256() external returns (int256) {
        int256 x = type(int256).min / int256(-1);
        count += 1;
        return x;
    }

    function mod256MinusOne() external returns (int256) {
        int256 x = type(int256).min % int256(-1);
        count += 1;
        return x;
    }
}
